from contextlib import contextmanager

@contextmanager
def tx(name):
    print("begin", name)
    try:
        yield name
        print("commit", name)
    except ValueError:
        print("rollback", name)
        raise
    finally:
        print("release", name)

try:
    with tx("t1"):
        raise ValueError("bad row")
except ValueError as e:
    print("caught", e)
